const fs = require('fs');

let app = fs.readFileSync('../src/app/App.tsx', 'utf-8');

// 1. Input: change to WASD
app = app.replace(
  `      // ── Player movement ──
      const moveSpeed = 6 * (1 + (eng.levelSpeedBoost > 0 ? 0.3 : 0)) * eng.scale * dt;
      if (eng.keys?.KeyW || eng.keys?.ArrowUp) eng.player.y -= moveSpeed;
      if (eng.keys?.KeyS || eng.keys?.ArrowDown) eng.player.y += moveSpeed;
      if (eng.keys?.KeyA || eng.keys?.ArrowLeft) eng.player.x -= moveSpeed;
      if (eng.keys?.KeyD || eng.keys?.ArrowRight) eng.player.x += moveSpeed;`,
  `      // ── Player movement ──
      const moveSpeed = 6 * (1 + (eng.levelSpeedBoost > 0 ? 0.3 : 0)) * eng.scale * dt;
      if (eng.keys?.KeyW || eng.keys?.ArrowUp) eng.player.y -= moveSpeed;
      if (eng.keys?.KeyS || eng.keys?.ArrowDown) eng.player.y += moveSpeed;
      if (eng.keys?.KeyA || eng.keys?.ArrowLeft) eng.player.x -= moveSpeed;
      if (eng.keys?.KeyD || eng.keys?.ArrowRight) eng.player.x += moveSpeed;`
);

// 2. Infinite Space Enemy Spawns
app = app.replace(
  /if\s*\(side === 0\)\s*{\s*x = Math\.random\(\) \* eng\.w;\s*y = -50;\s*}/,
  `if      (side === 0) { x = eng.player.x + (Math.random() - 0.5) * eng.w; y = eng.player.y - eng.h/2 - 50; }`
);
app = app.replace(
  /else if\s*\(side === 1\)\s*{\s*x = Math\.random\(\) \* eng\.w;\s*y = eng\.h \+ 50;\s*}/,
  `else if (side === 1) { x = eng.player.x + (Math.random() - 0.5) * eng.w; y = eng.player.y + eng.h/2 + 50; }`
);
app = app.replace(
  /else if\s*\(side === 2\)\s*{\s*x = -50;\s*y = Math\.random\(\) \* eng\.h;\s*}/,
  `else if (side === 2) { x = eng.player.x - eng.w/2 - 50; y = eng.player.y + (Math.random() - 0.5) * eng.h; }`
);
app = app.replace(
  /else\s*{\s*x = eng\.w \+ 50;\s*y = Math\.random\(\) \* eng\.h;\s*}/,
  `else                 { x = eng.player.x + eng.w/2 + 50; y = eng.player.y + (Math.random() - 0.5) * eng.h; }`
);

// Infinite Space Bullet/Enemy despawn boundaries
app = app.replace(
  /b\.type !== 'bounce' && \(b\.x < -50 \|\| b\.x > eng\.w \+ 50 \|\| b\.y < -50 \|\| b\.y > eng\.h \+ 50\)/g,
  `b.type !== 'bounce' && (Math.hypot(b.x - eng.player.x, b.y - eng.player.y) > Math.max(eng.w, eng.h))`
);

app = app.replace(
  /en\.x < 0 \|\| en\.x > eng\.w \|\| en\.y < 0 \|\| en\.y > eng\.h/g,
  `en.x < eng.player.x - eng.w/2 || en.x > eng.player.x + eng.w/2 || en.y < eng.player.y - eng.h/2 || en.y > eng.player.y + eng.h/2`
);

// We need an invisible bounds for bounce bullets to bounce off screen bounds relative to player
app = app.replace(
  /if \(b\.x < 5 \|\| b\.x > eng\.w - 5\)/g,
  `if (b.x < eng.player.x - eng.w/2 + 5 || b.x > eng.player.x + eng.w/2 - 5)`
);
app = app.replace(
  /if \(b\.y < 5 \|\| b\.y > eng\.h - 5\)/g,
  `if (b.y < eng.player.y - eng.h/2 + 5 || b.y > eng.player.y + eng.h/2 - 5)`
);

// Sniper target
app = app.replace(
  /const tx = en\.x < eng\.w \/ 2 \? 50 \* eng\.scale : eng\.w - 50 \* eng\.scale;/,
  `const tx = en.x < eng.player.x ? eng.player.x - eng.w/3 : eng.player.x + eng.w/3;`
);
app = app.replace(
  /const ty = en\.y < eng\.h \/ 2 \? 50 \* eng\.scale : eng\.h - 50 \* eng\.scale;/,
  `const ty = en.y < eng.player.y ? eng.player.y - eng.h/3 : eng.player.y + eng.h/3;`
);

// Boss spawn
app = app.replace(
  /eng\.enemies\.push\(\{ x: eng\.w \/ 2, y: -100/g,
  `eng.enemies.push({ x: eng.player.x, y: eng.player.y - eng.h/2 - 100`
);

// Update grid drawing to infinite space grid
app = app.replace(
  /ctx\.translate\(eng\.bgGridOffset\.x % 40, eng\.bgGridOffset\.y % 40\);/,
  `ctx.translate((eng.w/2 - eng.player.x) % 40, (eng.h/2 - eng.player.y) % 40);`
);

fs.writeFileSync('../src/app/App.tsx', app);
console.log('Patched App.tsx for WASD and Infinite Space boundaries.');
